INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (1, 1, 1, 1118601648, 1, 1, 'Forum rules -- please read', 'DanW', 'dan@example.com', '75.199.170.193', 1, 0, '', 'Welcome to Aperture Photography Community. A few ground rules so this stays a friendly place:<br /><br />1. Be civil. Critique the photo, not the photographer.<br />2. No hotlinking images from other people&#039;s sites. Host your own (Flickr, Photobucket, your own web space).<br />3. Keep images to 800 pixels on the long side, and no more than three per post in Photo Critique.<br />4. Only post photos you took yourself.<br />5. No commercial spam. Members&#039; classifieds go in Buy, Sell &amp; Trade.<br />6. Brand wars (Canon vs Nikon vs everybody) are allowed in Gear Talk only, and only while they stay polite.<br /><br />If something looks wrong, use the Report to Moderator link under the post rather than replying to it.<br /><br />Thanks, and enjoy the forum.<br />Dan', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (1, 1, 1, 1, 1, 1, 1, 0, 0, 4120, 1);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (3, 2, 1, 1181373305, 1, 3, 'New server -- everything should be faster now', 'DanW', 'dan@example.com', '41.232.108.220', 1, 0, '', 'We moved to a new host overnight. The forum was read-only for about three hours, sorry about that.<br /><br />Everything should be noticeably quicker, especially the search. If you see any errors, or your avatar went missing, post here and I&#039;ll look at it.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (4, 2, 1, 1181379768, 6, 4, 'Re: New server -- everything should be faster now', 'bugsnapper', 'bugsnapper@example.com', '180.228.180.90', 1, 0, '', 'Pages are loading much faster for me. Nice work Dan.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (5, 2, 1, 1181400436, 16, 5, 'Re: New server -- everything should be faster now', 'sunny_d', 'sunny_d@example.com', '66.141.183.47', 1, 0, '', 'My avatar is fine but I got logged out, is that normal?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (6, 2, 1, 1181403032, 1, 6, 'Re: New server -- everything should be faster now', 'DanW', 'dan@example.com', '207.17.16.121', 1, 0, '', '[quote author=sunny_d link=topic=2.msg5#msg5 date=1181400436]My avatar is fine but I got logged out, is that normal?[/quote]<br />Yes, the cookies were reset with the move. Just log in again and tick &quot;Always stay logged in&quot;.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (2, 0, 1, 3, 6, 1, 1, 0, 3, 612, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (19, 3, 1, 1183284012, 1, 19, 'July 2007 photo contest: Water', 'DanW', 'dan@example.com', '132.220.75.150', 1, 0, '', 'This month&#039;s theme is [b]Water[/b]. Rivers, rain, puddles, fountains, the ocean, a glass on the kitchen table -- anything goes as long as water is the subject.<br /><br />- One entry per member, taken this year.<br />- Post your entry as a reply to this topic, 800px max.<br />- Entries close July 31. Voting will be a poll in this board during the first week of August.<br /><br />The winner picks next month&#039;s theme. Good luck!', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (23, 3, 1, 1183486934, 11, 23, 'Re: July 2007 photo contest: Water', 'f8andbethere', 'f8andbethere@example.com', '101.3.217.19', 1, 0, '', 'Here&#039;s mine: the fountain at Cesar Chavez Plaza at lunchtime. 1/1000 to freeze the spray.<br />[url=http://www.flickr.com/photos/f8andbethere/]Fountain, Sacramento[/url]', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (36, 3, 1, 1183876830, 18, 36, 'Re: July 2007 photo contest: Water', 'woodsmoke', 'woodsmoke@example.com', '208.204.225.69', 1, 0, '', 'Morning mist on the Winooski River, about ten minutes after sunrise. Bronica, Velvia 100, scanned on my Epson 4490.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (74, 3, 1, 1184447752, 3, 74, 'Re: July 2007 photo contest: Water', 'harborlight', 'harborlight@example.com', '198.252.178.172', 1, 0, '', 'I&#039;m going to try for something at the coast next weekend. Is it OK to post an entry from the harbor shots?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (76, 3, 1, 1184486627, 1, 76, 'Re: July 2007 photo contest: Water', 'DanW', 'dan@example.com', '162.171.232.85', 1, 0, '', '[quote author=harborlight link=topic=3.msg74#msg74 date=1184447752]Is it OK to post an entry from the harbor shots?[/quote]<br />Sure, as long as water is the main subject and it was taken this year.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (116, 3, 1, 1184951525, 6, 116, 'Re: July 2007 photo contest: Water', 'bugsnapper', 'bugsnapper@example.com', '116.222.199.98', 1, 0, '', 'Dew drops on a spider web count, right? ;)', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (3, 1, 1, 19, 116, 1, 6, 0, 5, 1388, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (124, 4, 2, 1184967047, 16, 124, 'iPhone camera vs a real one?', 'sunny_d', 'sunny_d@example.com', '145.55.5.24', 1, 0, '', 'My brother-in-law waited in line for an iPhone on the 29th and now he&#039;s telling everyone he doesn&#039;t need a camera anymore. It&#039;s 2 megapixels with no flash and no zoom. Am I crazy or is that a step backwards from my S3?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (125, 4, 2, 1184969131, 10, 125, 'Re: iPhone camera vs a real one?', 'pixelpusher', 'pixelpusher@example.com', '58.225.202.195', 1, 0, '', 'It&#039;s a phone camera. In good daylight it&#039;s surprisingly decent for a phone, indoors it falls apart like they all do. Your S3 has a 12x zoom and image stabilization, it&#039;s not even the same category.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (130, 4, 2, 1185007223, 7, 130, 'Re: iPhone camera vs a real one?', 'oldschoolshooter', 'oldschoolshooter@example.com', '139.51.242.127', 1, 0, '', 'The best camera is the one you have with you. That said, I&#039;ll keep carrying the F100 and you can all laugh at me.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (134, 4, 2, 1185012760, 12, 134, 'Re: iPhone camera vs a real one?', 'jkowalski', 'jkowalski@example.com', '114.239.143.234', 1, 0, '', 'Has anyone actually seen pictures from it posted on Flickr yet? Curious what the colour looks like.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (139, 4, 2, 1185017452, 16, 139, 'Re: iPhone camera vs a real one?', 'sunny_d', 'sunny_d@example.com', '38.63.203.3', 1, 0, '', '[quote author=jkowalski link=topic=4.msg134#msg134 date=1185012760]Has anyone actually seen pictures from it posted on Flickr yet?[/quote]<br />There&#039;s already a Flickr group for it. Daylight shots look OK. Anything at night is mush.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (143, 4, 2, 1185025964, 5, 143, 'Re: iPhone camera vs a real one?', 'vista_steve', 'vista_steve@example.com', '171.48.238.36', 1, 0, '', 'Six hundred bucks for the 8GB model plus a two-year AT&amp;T contract. For that money I&#039;d rather have a D40 kit and a cheap phone. :)', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (4, 0, 2, 124, 143, 16, 5, 0, 5, 418, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (46, 5, 2, 1184008839, 2, 46, 'Seattle photo walk, Saturday July 28', 'nightshooter', 'nightshooter@example.com', '66.206.140.104', 1, 0, '', 'A few of us are meeting at the Pike Place Market sign at 7:30am on Saturday the 28th, before the crowds get there. We&#039;ll walk down to the waterfront and finish at Olympic Sculpture Park, then coffee.<br /><br />Any gear is welcome, phones included. I&#039;ve added it to the forum calendar. Reply here if you&#039;re coming so I know how many to expect.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (48, 5, 2, 1184024466, 13, 48, 'Re: Seattle photo walk, Saturday July 28', 'tlee_photo', 'tlee_photo@example.com', '176.247.10.158', 1, 0, '', 'I&#039;m in, if the ferry cooperates.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (49, 5, 2, 1184055340, 9, 49, 'Re: Seattle photo walk, Saturday July 28', 'maria_lens', 'maria_lens@example.com', '84.240.28.117', 1, 0, '', 'Wish I could, Austin is a bit far. Post the results!', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (66, 5, 2, 1184270570, 3, 66, 'Re: Seattle photo walk, Saturday July 28', 'harborlight', 'harborlight@example.com', '172.253.205.246', 1, 0, '', 'Portland is close enough. I&#039;ll drive up Friday night. :)', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (126, 5, 2, 1184971236, 2, 126, 'Re: Seattle photo walk, Saturday July 28', 'nightshooter', 'nightshooter@example.com', '125.170.250.227', 1, 0, '', 'That&#039;s six people so far. Forecast says overcast, which is good light for the market anyway.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (5, 0, 2, 46, 126, 2, 2, 0, 4, 302, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (9, 6, 2, 1182975086, 12, 9, 'What got you into photography?', 'jkowalski', 'jkowalski@example.com', '42.37.12.199', 1, 0, '', 'New guy question. What got everyone started? For me it was a trip to Yellowstone last year and realizing all my point and shoot pictures looked flat.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (10, 6, 2, 1182979823, 7, 10, 'Re: What got you into photography?', 'oldschoolshooter', 'oldschoolshooter@example.com', '138.202.251.90', 1, 0, '', 'My dad&#039;s Pentax Spotmatic in 1966 and a darkroom in the basement that smelled like fixer. Never looked back.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (13, 6, 2, 1183023872, 9, 13, 'Re: What got you into photography?', 'maria_lens', 'maria_lens@example.com', '186.149.49.114', 1, 0, '', 'Took a night class at the community college in 2002 because my friend didn&#039;t want to go alone. She quit after three weeks. I&#039;m still here.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (14, 6, 2, 1183053754, 15, 14, 'Re: What got you into photography?', 'rmcallister', 'rmcallister@example.com', '205.108.237.80', 1, 0, '', 'Birds. Wanted to know what I was looking at through the binoculars, so I bought a long lens. Then a longer one.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (15, 6, 2, 1183206411, 11, 15, 'Re: What got you into photography?', 'f8andbethere', 'f8andbethere@example.com', '158.14.251.231', 1, 0, '', 'Cartier-Bresson book in a used bookshop. Still the best $4 I ever spent.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (6, 0, 2, 9, 15, 12, 11, 0, 4, 655, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (94, 7, 3, 1184785506, 12, 94, 'Nikon D40 vs Canon 400D, again', 'jkowalski', 'jkowalski@example.com', '82.251.58.153', 1, 0, '', 'I know this gets asked every week, sorry. I&#039;m finally moving up from my A620 and it&#039;s between the Nikon D40 kit and the Canon 400D (Rebel XTi here) kit. Best Buy has the D40 with the 18-55 for $599 and the XTi kit for $749.<br /><br />Mostly family stuff, my kids&#039; soccer, and some landscapes on vacation. Budget is tight so the lens will be the kit lens for a while.<br /><br />I put a poll on the topic too. What would you buy?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (95, 7, 3, 1184788119, 5, 95, 'Re: Nikon D40 vs Canon 400D, again', 'vista_steve', 'vista_steve@example.com', '61.33.99.152', 1, 0, '', 'Both are fine cameras. The D40 feels better in the hand to me and the screen is bigger. Big catch: it has no focus motor in the body, so older AF lenses won&#039;t autofocus on it. Only AF-S lenses do.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (97, 7, 3, 1184790643, 3, 97, 'Re: Nikon D40 vs Canon 400D, again', 'harborlight', 'harborlight@example.com', '153.82.240.53', 1, 0, '', 'I have the 400D and love it. 10 megapixels vs 6, the sensor cleaning thing actually works, and the 50mm f/1.8 is under $90 when you want to try a fast lens.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (99, 7, 3, 1184831732, 12, 99, 'Re: Nikon D40 vs Canon 400D, again', 'jkowalski', 'jkowalski@example.com', '49.141.17.187', 1, 0, '', '[quote author=vista_steve link=topic=7.msg95#msg95 date=1184788119]Only AF-S lenses do.[/quote]<br />Is that a big deal? I don&#039;t own any Nikon lenses so I&#039;d be buying new anyway.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (103, 7, 3, 1184847602, 2, 103, 'Re: Nikon D40 vs Canon 400D, again', 'nightshooter', 'nightshooter@example.com', '116.11.18.126', 1, 0, '', 'Not a big deal if you&#039;re starting from zero, but it matters for the cheap primes. The Nikon 50mm f/1.8 is AF, not AF-S, so it&#039;s manual focus on a D40.<br /><br />For soccer the 400D&#039;s 9-point AF will help a bit. Honestly though, go hold both in the store. The one that feels right is the one you&#039;ll take with you.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (105, 7, 3, 1184866589, 14, 105, 'Re: Nikon D40 vs Canon 400D, again', 'Kat_B', 'kat_b@example.com', '67.232.72.251', 1, 0, '', 'I bought the D40 in May and I&#039;m happy with it. The help screens in the menus are nice when you&#039;re learning what everything does. 6MP is plenty for 8x10s.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (122, 7, 3, 1184965823, 7, 122, 'Re: Nikon D40 vs Canon 400D, again', 'oldschoolshooter', 'oldschoolshooter@example.com', '100.58.125.112', 1, 0, '', 'Megapixels are the least important number on either spec sheet. Buy whichever, then spend the next $100 on a decent bag and a book on composition, not a second lens.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (136, 7, 3, 1185015730, 12, 136, 'Re: Nikon D40 vs Canon 400D, again', 'jkowalski', 'jkowalski@example.com', '98.147.84.230', 1, 0, '', 'Thanks everyone. Leaning towards the 400D because of the 50mm f/1.8 thing, and my brother-in-law shoots Canon so I can borrow his 70-300. ;D', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (142, 7, 3, 1185021609, 7, 142, 'Re: Nikon D40 vs Canon 400D, again', 'oldschoolshooter', 'oldschoolshooter@example.com', '164.154.102.86', 1, 0, '', '[quote author=jkowalski link=topic=7.msg136#msg136 date=1185015730]my brother-in-law shoots Canon so I can borrow his 70-300[/quote]<br />That&#039;s the best reason anyone has given in one of these threads. Borrowing glass beats any spec sheet. Post some soccer shots once you&#039;ve got it.', 'xx');
