INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (61, 8, 3, 1184250020, 11, 61, 'Canon 40D rumors -- announcement in August?', 'f8andbethere', 'f8andbethere@example.com', '178.212.91.1', 1, 0, '', 'Rumor sites are saying a 30D replacement is coming in August. 10MP, bigger screen, live view. Anyone hearing anything solid, or is it all forum noise?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (63, 8, 3, 1184266315, 1, 63, 'Re: Canon 40D rumors -- announcement in August?', 'DanW', 'dan@example.com', '97.31.219.82', 1, 0, '', 'If it&#039;s real I&#039;ll probably skip it. My 30D is still doing everything I ask of it.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (67, 8, 3, 1184315439, 15, 67, 'Re: Canon 40D rumors -- announcement in August?', 'rmcallister', 'rmcallister@example.com', '201.35.28.125', 1, 0, '', 'Faster burst would be nice for birds. I&#039;ll wait for actual reviews before getting excited.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (108, 8, 3, 1184883400, 11, 108, 'Re: Canon 40D rumors -- announcement in August?', 'f8andbethere', 'f8andbethere@example.com', '72.53.242.196', 1, 0, '', 'Another &quot;leaked&quot; spec sheet this week. Same specs as before, so maybe there&#039;s something to it.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (8, 0, 3, 61, 108, 11, 11, 0, 3, 734, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (28, 9, 3, 1183665900, 15, 28, 'Sigma 50-500 &quot;Bigma&quot; -- worth it?', 'rmcallister', 'rmcallister@example.com', '154.103.59.25', 1, 0, '', 'Six months with the Bigma now. Heavy, a bit soft wide open at 500, sharp at f/8. For the price nothing else gets me to 500mm. Happy to answer questions.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (30, 9, 3, 1183713634, 4, 30, 'Re: Sigma 50-500 &quot;Bigma&quot; -- worth it?', 'graytones', 'graytones@example.com', '40.74.100.243', 1, 0, '', 'How do you carry it? My 18-200 already feels heavy after a day out.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (32, 9, 3, 1183747449, 15, 32, 'Re: Sigma 50-500 &quot;Bigma&quot; -- worth it?', 'rmcallister', 'rmcallister@example.com', '126.170.72.166', 1, 0, '', 'Monopod and a sling strap. Your arms get used to it. Eventually.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (9, 0, 3, 28, 32, 15, 15, 0, 2, 287, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (16, 10, 3, 1183210815, 16, 16, 'Cheap tripod recommendations under $100?', 'sunny_d', 'sunny_d@example.com', '123.56.252.72', 1, 0, '', 'Looking for something that won&#039;t fall over in a breeze. Under $100 if possible. Suggestions?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (17, 10, 3, 1183215756, 2, 17, 'Re: Cheap tripod recommendations under $100?', 'nightshooter', 'nightshooter@example.com', '152.170.246.8', 1, 0, '', 'Save up for a Manfrotto 190 and a decent head. Buying a cheap tripod first and the good one later costs more in the end, ask me how I know.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (18, 10, 3, 1183273892, 18, 18, 'Re: Cheap tripod recommendations under $100?', 'woodsmoke', 'woodsmoke@example.com', '153.93.151.217', 1, 0, '', 'Agree with nightshooter. If you really must stay under $100, look at used Bogen/Manfrotto on eBay.', 'xx');
