INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (59, 12, 8, 1184202728, 5, 59, 'Re: WTB: Nikon SB-600', 'vista_steve', 'vista_steve@example.com', '156.41.165.77', 1, 0, '', 'Keep an eye on KEH&#039;s site, they had a couple listed at &quot;EX&quot; grade last week.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (12, 0, 8, 56, 59, 14, 5, 0, 1, 95, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (117, 13, 5, 1184955920, 5, 117, 'Vista and my card reader, ugh', 'vista_steve', 'vista_steve@example.com', '166.241.156.177', 1, 0, '', 'Since the last round of Windows updates my USB card reader takes forever to show up in Vista, and then the import from Lightroom crawls. Same reader was fine on my old XP box. Anyone else?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (120, 13, 5, 1184960456, 10, 120, 'Re: Vista and my card reader, ugh', 'pixelpusher', 'pixelpusher@example.com', '192.191.74.192', 1, 0, '', 'Try a different USB port, ideally one directly on the back of the computer, not a hub. And check the manufacturer&#039;s site for a Vista driver, a lot of the cheap readers still don&#039;t have one.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (127, 13, 5, 1184975932, 5, 127, 'Re: Vista and my card reader, ugh', 'vista_steve', 'vista_steve@example.com', '167.218.163.8', 1, 0, '', 'Back port is a little better. No Vista driver for mine of course. :(', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (137, 13, 5, 1185015788, 4, 137, 'Re: Vista and my card reader, ugh', 'graytones', 'graytones@example.com', '206.131.57.82', 1, 0, '', 'I gave up and bought a new SanDisk reader for 20 quid. Vista picked it up straight away. Sometimes it&#039;s just not worth the fight.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (13, 0, 5, 117, 137, 5, 4, 0, 3, 233, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (7, 14, 5, 1182845424, 10, 7, 'Lightroom 1.1 update -- worth installing?', 'pixelpusher', 'pixelpusher@example.com', '80.129.33.95', 1, 0, '', 'Lightroom 1.1 is out (free update for 1.0 owners). Highlights: new Clarity slider, better sharpening, catalogs replace libraries, and the import is faster.<br /><br />I&#039;ve run it on my MacBook Pro for two days now, no problems. Back up your library before you let it convert, just in case.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (8, 14, 5, 1182861008, 2, 8, 'Re: Lightroom 1.1 update -- worth installing?', 'nightshooter', 'nightshooter@example.com', '77.118.171.240', 1, 0, '', 'Clarity alone is worth it. Upgraded last night, converted about 9,000 photos without a hiccup.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (11, 14, 5, 1182984063, 11, 11, 'Re: Lightroom 1.1 update -- worth installing?', 'f8andbethere', 'f8andbethere@example.com', '50.219.146.246', 1, 0, '', 'Is it much different from just using Bridge and Camera Raw in CS3?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (12, 14, 5, 1183017328, 10, 12, 'Re: Lightroom 1.1 update -- worth installing?', 'pixelpusher', 'pixelpusher@example.com', '46.246.74.37', 1, 0, '', '[quote author=f8andbethere link=topic=14.msg11#msg11 date=1182984063]Is it much different from just using Bridge and Camera Raw in CS3?[/quote]<br />Same RAW engine underneath, but the library side is much better for sorting a big shoot. Try the trial and see.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (14, 0, 5, 7, 12, 10, 10, 0, 3, 961, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (39, 15, 5, 1183926023, 14, 39, 'Photoshop CS3 vs Elements 5 for a beginner?', 'Kat_B', 'kat_b@example.com', '100.167.42.138', 1, 0, '', 'CS3 is $649 and Elements 5 is $89. As a beginner, is there anything in CS3 I&#039;d actually miss?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (41, 15, 5, 1183928524, 10, 41, 'Re: Photoshop CS3 vs Elements 5 for a beginner?', 'pixelpusher', 'pixelpusher@example.com', '27.165.47.81', 1, 0, '', 'Not for a while. Elements does layers, levels and curves (sort of). Get Elements, or Lightroom if you shoot RAW, and spend the rest on a lens.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (45, 15, 5, 1183970017, 9, 45, 'Re: Photoshop CS3 vs Elements 5 for a beginner?', 'maria_lens', 'maria_lens@example.com', '170.160.143.187', 1, 0, '', 'If you&#039;re a student, the education price on CS3 is a lot more reasonable. Otherwise Elements.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (15, 0, 5, 39, 45, 14, 9, 0, 2, 402, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (128, 16, 7, 1184999415, 16, 128, 'Deathly Hallows -- NO SPOILERS thread', 'sunny_d', 'sunny_d@example.com', '202.66.76.1', 1, 0, '', 'Got my copy at the midnight release at Barnes &amp; Noble. 200 pages in. Please, nobody post spoilers anywhere on the forum for at least a week!', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (129, 16, 7, 1185005702, 2, 129, 'Re: Deathly Hallows -- NO SPOILERS thread', 'nightshooter', 'nightshooter@example.com', '107.21.206.172', 1, 0, '', 'Agreed. Spoilers in any board will be removed, and the poster gets a stern talking-to.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (135, 16, 7, 1185013226, 9, 135, 'Re: Deathly Hallows -- NO SPOILERS thread', 'maria_lens', 'maria_lens@example.com', '130.114.113.57', 1, 0, '', 'Mine arrives from Amazon today. I&#039;m staying off the internet until it does. Except here, apparently.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (16, 0, 7, 128, 135, 16, 9, 0, 2, 188, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (96, 17, 7, 1184788935, 4, 96, 'Anyone upgrading to a Core 2 Duo?', 'graytones', 'graytones@example.com', '99.238.92.57', 1, 0, '', 'My Athlon XP is really struggling with D200 RAW files. Thinking about a Core 2 Duo E6600 with 2GB. Worth it, or wait for quad core prices to drop?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (101, 17, 7, 1184834744, 10, 101, 'Re: Anyone upgrading to a Core 2 Duo?', 'pixelpusher', 'pixelpusher@example.com', '63.111.54.127', 1, 0, '', 'The E6600 is a big jump from an Athlon XP. Get 2GB of RAM minimum, 4 if you&#039;re on 64-bit (though good luck with drivers).', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (109, 17, 7, 1184886906, 5, 109, 'Re: Anyone upgrading to a Core 2 Duo?', 'vista_steve', 'vista_steve@example.com', '93.64.129.245', 1, 0, '', 'Intel cut prices this week, so check again before you buy.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (123, 17, 7, 1184966242, 3, 123, 'Re: Anyone upgrading to a Core 2 Duo?', 'harborlight', 'harborlight@example.com', '129.145.3.73', 1, 0, '', 'I just did this in the spring. Lightroom went from painful to perfectly fine. Don&#039;t skimp on the hard drive either, RAW files add up fast.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (17, 0, 7, 96, 123, 4, 3, 0, 3, 276, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (34, 18, 7, 1183847436, 12, 34, 'Summer movies: Transformers or Ratatouille?', 'jkowalski', 'jkowalski@example.com', '48.143.174.159', 1, 0, '', 'Took the kids to Ratatouille, then went back alone for Transformers. Liked Ratatouille more, which surprised me.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (37, 18, 7, 1183889441, 7, 37, 'Re: Summer movies: Transformers or Ratatouille?', 'oldschoolshooter', 'oldschoolshooter@example.com', '102.200.254.59', 1, 0, '', 'Ratatouille. Some of those shots of Paris at night look like they were lit by a cinematographer, not a computer.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (43, 18, 7, 1183948919, 17, 43, 'Re: Summer movies: Transformers or Ratatouille?', 'marcusR', 'marcusr@example.com', '57.111.166.94', 1, 0, '', 'Transformers. Giant robots. Not sorry. :D', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (18, 0, 7, 34, 43, 12, 17, 0, 2, 233, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (2, 19, 4, 1138995032, 9, 2, 'Critique guidelines -- read before posting', 'maria_lens', 'maria_lens@example.com', '184.84.99.234', 1, 0, '', 'Welcome to Photo Critique. To get useful feedback:<br /><br />[b]When posting:[/b]<br />- Resize to 800px on the long side. Link or embed, both are fine.<br />- Max three photos per topic.<br />- Tell us what you were going for and what kind of feedback you want.<br />- Camera, lens and settings help, but aren&#039;t required.<br /><br />[b]When replying:[/b]<br />- Say what works, not only what doesn&#039;t.<br />- Be specific. &quot;Nice&quot; doesn&#039;t help anyone. &quot;The horizon is tilted about 2 degrees&quot; does.<br />- If you post an edit of someone&#039;s photo, ask first.<br /><br />Thanks!<br />maria', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (20, 19, 4, 1183364139, 2, 20, 'Re: Critique guidelines -- read before posting', 'nightshooter', 'nightshooter@example.com', '77.104.135.51', 1, 0, '', 'Small update: Flickr links are fine and preferred. Please don&#039;t hotlink from MySpace, those images expire and the thread ends up full of red X&#039;s.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (19, 1, 4, 2, 20, 9, 2, 0, 1, 3402, 1);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (132, 20, 4, 1185009298, 3, 132, 'C&amp;C welcome: sunset over the harbor', 'harborlight', 'harborlight@example.com', '43.81.249.80', 1, 0, '', 'Took this last night down at the harbor, right around sunset. Canon 400D, kit lens, f/8 at 1/125, ISO 100. Tried to time it so the light hit the water just right.<br /><br />[url=http://www.flickr.com/photos/harborlight/]Sunset, Commercial Street pier[/url] (on Flickr)<br /><br />Would love some feedback on the composition -- I keep going back and forth on whether the horizon should be lower.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (133, 20, 4, 1185012127, 4, 133, 'Re: C&amp;C welcome: sunset over the harbor', 'graytones', 'graytones@example.com', '172.32.179.116', 1, 0, '', 'Really nice colour in the sky. I&#039;d probably crop a touch off the left side, there&#039;s some dead space by the piling. Otherwise this is a solid shot for a kit lens.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (138, 20, 4, 1185016806, 6, 138, 'Re: C&amp;C welcome: sunset over the harbor', 'bugsnapper', 'bugsnapper@example.com', '28.27.34.151', 1, 0, '', 'Lovely colour. Was that straight out of camera or did you bump the saturation? The 400D&#039;s Standard picture style can get a bit hot in the reds.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (140, 20, 4, 1185018098, 3, 140, 'Re: C&amp;C welcome: sunset over the harbor', 'harborlight', 'harborlight@example.com', '86.185.254.193', 1, 0, '', '[quote author=bugsnapper link=topic=20.msg138#msg138 date=1185016806]Was that straight out of camera or did you bump the saturation?[/quote]<br />Shot RAW, converted in Digital Photo Professional with +10 saturation, and that&#039;s it. The sky really was that orange. :)', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (144, 20, 4, 1185027286, 2, 144, 'Re: C&amp;C welcome: sunset over the harbor', 'nightshooter', 'nightshooter@example.com', '187.103.165.203', 1, 0, '', '[quote author=harborlight link=topic=20.msg132#msg132 date=1185009298]Would love some feedback on the composition -- I keep going back and forth on whether the horizon should be lower.[/quote]<br />Agree with graytones on the crop. I&#039;d also pull the shadows up slightly, there&#039;s some detail hiding in the pilings. The horizon is fine where it is, on the lower third. Lowering it further would just give you more sky and the sky isn&#039;t the interesting part.<br /><br />Also, the Flickr version is 1024 wide, guidelines say 800. ;)', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (145, 20, 4, 1185028826, 5, 145, 'Re: C&amp;C welcome: sunset over the harbor', 'vista_steve', 'vista_steve@example.com', '164.236.156.58', 1, 0, '', 'Good light. Off topic, but is anyone else&#039;s Vista box slow to import off a card reader? I&#039;ll take it to the other thread.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (146, 20, 4, 1185030346, 3, 146, 'Re: C&amp;C welcome: sunset over the harbor', 'harborlight', 'harborlight@example.com', '121.202.231.173', 1, 0, '', 'Thanks all, I&#039;ll try a tighter crop and lift the shadows. Figured the piling added some context but you&#039;re probably right that it&#039;s just dead space.<br /><br />[quote author=nightshooter link=topic=20.msg144#msg144 date=1185027286]Also, the Flickr version is 1024 wide, guidelines say 800. ;)[/quote]<br />Oops. Fixed. :-[', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (20, 0, 4, 132, 146, 3, 3, 0, 6, 221, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (118, 21, 4, 1184956240, 6, 118, 'First attempt at macro photography', 'bugsnapper', 'bugsnapper@example.com', '124.147.56.167', 1, 0, '', 'Picked up a Tamron 90mm f/2.8 macro last week. First real outing: a jumping spider on the deck rail, f/11, 1/180, pop-up flash through a diffuser made from a Pringles can. Not joking.<br /><br />[url=http://www.flickr.com/photos/bugsnapper/]Jumping spider, 1:1[/url]<br /><br />Focus is on the front eyes. Is the background too busy?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (121, 21, 4, 1184961959, 7, 121, 'Re: First attempt at macro photography', 'oldschoolshooter', 'oldschoolshooter@example.com', '70.32.60.135', 1, 0, '', 'The Pringles can deserves an award. Eyes are sharp, which is what matters. Background is fine, it&#039;s all mush at that magnification anyway.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (131, 21, 4, 1185008418, 9, 131, 'Re: First attempt at macro photography', 'maria_lens', 'maria_lens@example.com', '210.10.202.102', 1, 0, '', 'Great detail. I&#039;d crop a bit tighter from the bottom, the rail edge pulls my eye away from the spider.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (141, 21, 4, 1185018539, 4, 141, 'Re: First attempt at macro photography', 'graytones', 'graytones@example.com', '170.4.202.87', 1, 0, '', 'Brilliant. Mine would have jumped on the lens and I&#039;d have run off screaming.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (21, 0, 4, 118, 141, 6, 4, 0, 3, 389, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (111, 22, 4, 1184933412, 8, 111, 'Please critique my daughter&#039;s portrait series', 'dadwithcanon', 'dadwithcanon@example.com', '102.193.91.36', 1, 0, '', 'Brand new member, brand new 400D. These are three shots of my daughter in the backyard, late afternoon, kit lens at 55mm.<br />[url=http://www.flickr.com/photos/dadwithcanon/]Backyard portraits (3)[/url]<br /><br />Be honest, I want to get better.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (113, 22, 4, 1184941360, 9, 113, 'Re: Please critique my daughter&#039;s portrait series', 'maria_lens', 'maria_lens@example.com', '29.241.86.51', 1, 0, '', 'Welcome! The second one is the strongest, nice catchlight in her eyes. On the first and third the background is too busy. Try moving so there&#039;s more distance between her and the fence, and shoot at f/5.6 to soften it.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (114, 22, 4, 1184947504, 13, 114, 'Re: Please critique my daughter&#039;s portrait series', 'tlee_photo', 'tlee_photo@example.com', '190.130.121.107', 1, 0, '', 'Agree with maria on #2. On #3 her elbow is cut off at the joint, try to crop between joints instead.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (119, 22, 4, 1184959690, 3, 119, 'Re: Please critique my daughter&#039;s portrait series', 'harborlight', 'harborlight@example.com', '177.228.224.123', 1, 0, '', 'The light in #2 is lovely. Late afternoon is the best time of day for this, you picked well.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (22, 0, 4, 111, 119, 8, 3, 0, 3, 142, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (107, 23, 4, 1184881219, 4, 107, 'B&amp;W conversion -- too harsh?', 'graytones', 'graytones@example.com', '124.175.193.149', 1, 0, '', 'Converted this one from colour using the channel mixer, heavy on the red channel. Terraced houses in Hyde Park, Leeds.<br />[url=http://www.flickr.com/photos/graytones/]Terraces, B&amp;W[/url]<br /><br />Is it too contrasty? I like it but I&#039;ve been staring at it for an hour.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (110, 23, 4, 1184922904, 7, 110, 'Re: B&amp;W conversion -- too harsh?', 'oldschoolshooter', 'oldschoolshooter@example.com', '189.167.77.67', 1, 0, '', 'It&#039;s a bit crunchy in the sky. Back the red off a little. Looks like red filter on Tri-X, which isn&#039;t a bad thing.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (115, 23, 4, 1184950311, 2, 115, 'Re: B&amp;W conversion -- too harsh?', 'nightshooter', 'nightshooter@example.com', '44.237.116.239', 1, 0, '', 'The midtones on the brick work really well. I&#039;d ease off on the sky like oldschool said, there&#039;s some haloing along the roofline.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (23, 0, 4, 107, 115, 4, 2, 0, 2, 98, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (100, 24, 4, 1184833228, 2, 100, 'Long exposure at the pier -- thoughts?', 'nightshooter', 'nightshooter@example.com', '105.221.216.82', 1, 0, '', '30 seconds at f/16 with a 3-stop ND, about twenty minutes after sunset. Alki Beach, looking toward downtown.<br />[url=http://www.flickr.com/photos/nightshooter/]Alki, 30s[/url]<br /><br />Going for flat water. Is the city too small in the frame?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (104, 24, 4, 1184851823, 10, 104, 'Re: Long exposure at the pier -- thoughts?', 'pixelpusher', 'pixelpusher@example.com', '205.148.142.72', 1, 0, '', 'Water came out like glass, nice. The city is fine small, it&#039;s a seascape not a skyline shot.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (106, 24, 4, 1184871778, 18, 106, 'Re: Long exposure at the pier -- thoughts?', 'woodsmoke', 'woodsmoke@example.com', '161.254.202.132', 1, 0, '', 'Lovely. There&#039;s a hot pixel just above the third light on the right, easy to clone out.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (112, 24, 4, 1184940576, 5, 112, 'Re: Long exposure at the pier -- thoughts?', 'vista_steve', 'vista_steve@example.com', '72.240.97.218', 1, 0, '', 'How do you keep the tripod still on the sand for 30 seconds? Mine always sinks.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (24, 0, 4, 100, 112, 2, 5, 0, 3, 256, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (92, 25, 4, 1184772629, 14, 92, 'New D40 owner, first real attempt', 'Kat_B', 'kat_b@example.com', '98.129.13.177', 1, 0, '', 'First photo I&#039;m actually proud of: our neighbour&#039;s sunflowers, D40 kit lens at 55mm, f/5.6.<br />[url=http://www.flickr.com/photos/kat_b/]Sunflowers[/url]<br />What could I do better?', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (93, 25, 4, 1184784007, 16, 93, 'Re: New D40 owner, first real attempt', 'sunny_d', 'sunny_d@example.com', '143.98.148.31', 1, 0, '', 'Pretty! I like the bee on the left one.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (102, 25, 4, 1184841221, 7, 102, 'Re: New D40 owner, first real attempt', 'oldschoolshooter', 'oldschoolshooter@example.com', '149.205.121.213', 1, 0, '', 'Good start. Try getting lower so the flowers are against the sky instead of the garage. Two steps and a crouch would change the whole picture.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (25, 0, 4, 92, 102, 14, 7, 0, 2, 177, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (26, 26, 4, 1183628407, 12, 26, 'Fourth of July fireworks -- first try', 'jkowalski', 'jkowalski@example.com', '84.117.201.193', 1, 0, '', 'Borrowed my neighbour&#039;s tripod and tried fireworks over Navy Pier. Most were blurry, three came out. ISO 100, f/8, about 4 seconds each.<br />[url=http://www.flickr.com/photos/jkowalski/]Navy Pier fireworks[/url]', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (27, 26, 4, 1183638035, 2, 27, 'Re: Fourth of July fireworks -- first try', 'nightshooter', 'nightshooter@example.com', '155.252.143.133', 1, 0, '', 'For a first attempt those are good. Next year try bulb mode and a piece of black card over the lens between bursts, you can stack several in one frame.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (98, 26, 4, 1184792526, 6, 98, 'Re: Fourth of July fireworks -- first try', 'bugsnapper', 'bugsnapper@example.com', '42.32.173.200', 1, 0, '', 'Just found this thread. The third one is great, the trails look like a dandelion.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (26, 0, 4, 26, 98, 12, 6, 0, 2, 310, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (86, 27, 4, 1184625021, 13, 86, 'Wedding second-shooting: my first set', 'tlee_photo', 'tlee_photo@example.com', '204.252.18.226', 1, 0, '', 'Second-shot my first wedding on Saturday. Here are five I&#039;m happy with. The main photographer said the reception ones were too dark, curious what you think.<br />[url=http://www.flickr.com/photos/tlee_photo/]Wedding set[/url]', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (88, 27, 4, 1184663533, 9, 88, 'Re: Wedding second-shooting: my first set', 'maria_lens', 'maria_lens@example.com', '178.123.248.205', 1, 0, '', 'Ceremony shots are really nice, good angles. Reception: bounce the flash off the ceiling and drag the shutter to 1/30 to pick up the room light. And bring more batteries than you think.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (91, 27, 4, 1184751612, 13, 91, 'Re: Wedding second-shooting: my first set', 'tlee_photo', 'tlee_photo@example.com', '199.85.158.51', 1, 0, '', 'Thanks maria. I was on direct flash the whole time. Lesson learned.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (27, 0, 4, 86, 91, 13, 13, 0, 2, 205, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (81, 28, 4, 1184570417, 15, 81, 'Great blue heron at Mt Auburn', 'rmcallister', 'rmcallister@example.com', '39.44.12.214', 1, 0, '', 'Spent two hours at Auburn Lake for this one. Bigma at 500mm, f/8, 1/640, monopod.<br />[url=http://www.flickr.com/photos/rmcallister/]Heron, Mt Auburn Cemetery[/url]', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (83, 28, 4, 1184589043, 6, 83, 'Re: Great blue heron at Mt Auburn', 'bugsnapper', 'bugsnapper@example.com', '182.12.87.77', 1, 0, '', 'Worth the two hours. Lovely detail in the feathers.', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (89, 28, 4, 1184704209, 2, 89, 'Re: Great blue heron at Mt Auburn', 'nightshooter', 'nightshooter@example.com', '158.246.252.1', 1, 0, '', 'The reflection really makes this one. Nice timing on the head turn too.', 'xx');
INSERT INTO smf_topics (ID_TOPIC, isSticky, ID_BOARD, ID_FIRST_MSG, ID_LAST_MSG, ID_MEMBER_STARTED, ID_MEMBER_UPDATED, ID_POLL, numReplies, numViews, locked) VALUES (28, 0, 4, 81, 89, 15, 2, 0, 2, 166, 0);
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (73, 29, 4, 1184420408, 11, 73, 'Street: farmers market, Saturday morning', 'f8andbethere', 'f8andbethere@example.com', '47.53.61.179', 1, 0, '', 'Some candids from the Sunday market under the freeway. 35mm, shot from the hip on most of them.<br />[url=http://www.flickr.com/photos/f8andbethere/]Farmers market[/url]', 'xx');
INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (77, 29, 4, 1184487153, 7, 77, 'Re: Street: farmers market, Saturday morning', 'oldschoolshooter', 'oldschoolshooter@example.com', '56.13.163.42', 1, 0, '', 'The old man weighing peaches is the keeper. The rest are a bit tilted -- shooting from the hip will do that.', 'xx');
