INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (68, 31, 4, 1184318118, 9, 68, 'Re: Self-portrait attempt (be gentle)', 'maria_lens', 'maria_lens@example.com', '118.28.56.189', 1, 0, '', 'You don&#039;t look terrified! The window light is soft and even. Try turning your shoulders a little away from the camera, it&#039;s more flattering.', 'xx');
