INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (60, 32, 4, 1184229010, 10, 60, 'Re: HDR experiment -- too much?', 'pixelpusher', 'pixelpusher@example.com', '35.187.11.158', 1, 0, '', 'A little. The halos around the steeple give it away. Turn the strength down and the luminosity up, and it&#039;ll look more natural.', 'xx');
