INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (69, 32, 4, 1184364635, 5, 69, 'Re: HDR experiment -- too much?', 'vista_steve', 'vista_steve@example.com', '136.198.122.197', 1, 0, '', 'Ha. Fair enough. Redid it with less strength, much better.', 'xx');
