INSERT INTO smf_messages (ID_MSG, ID_TOPIC, ID_BOARD, posterTime, ID_MEMBER, ID_MSG_MODIFIED, subject, posterName, posterEmail, posterIP, smileysEnabled, modifiedTime, modifiedName, body, icon) VALUES (50, 35, 4, 1184069558, 2, 50, 'Re: Panning shots at the county fair', 'nightshooter', 'nightshooter@example.com', '84.155.3.13', 1, 0, '', 'One in ten is a good ratio for panning. Try 1/60 first and work slower as you get the hang of it.', 'xx');
